package com.ruoyi.ai.agent;
import com.fasterxml.jackson.databind.node.*;
import junit.framework.TestCase;
import static com.ruoyi.ai.agent.AgentJson.*;
public class B8cDeleteSheetManifestTest extends TestCase {
    static ObjectNode snapshot(){return (ObjectNode)parse("{\"id\":\"p\",\"sheetOrder\":[\"s\",\"keep\"],\"activeSheet\":\"s\",\"sheets\":{\"s\":{\"id\":\"s\",\"name\":\"Delete\",\"rowCount\":6,\"columnCount\":6,\"cellData\":{\"0\":{\"0\":{\"v\":\"lost\"}}}},\"keep\":{\"id\":\"keep\",\"name\":\"Keep\",\"rowCount\":6,\"columnCount\":6,\"cellData\":{\"0\":{\"0\":{\"v\":\"kept\"}}}}}} ");}
    static ObjectNode action(){ObjectNode a=obj().put("schemaVersion","2.0").put("type","deleteSheet").put("fallbackSheetId","keep").put("force",true);a.set("target",obj().put("sheetId","s"));return a;}
    static ArrayNode scopes(){return arr().add(obj().put("sheetId","s").put("range","A1:F6"));}
    private void reject(Runnable r){try{r.run();fail("unsafe delete accepted");}catch(IllegalArgumentException e){assertNotNull(e.getMessage());}}
    public void testDeleteRepairsActiveAndPreservesRemainingSheet(){ObjectNode before=snapshot(),m=StructureManifest.preview(before,action(),scopes()),saved=StructureManifest.apply(before,m);assertFalse(saved.path("sheets").has("s"));assertEquals("keep",saved.path("activeSheet").asText());assertEquals(arr().add("keep"),saved.path("sheetOrder"));assertEquals(before.path("sheets").path("keep"),saved.path("sheets").path("keep"));ObjectNode change=obj().put("kind","controlled-structure").put("operationId","call").put("afterHash",hash(saved));change.set("structurePatch",m.path("structurePatch"));ObjectNode write=obj().put("transportVersion",2).put("callId","call").put("persistenceStatus","SAVED").put("validation","PASSED").put("loadedRevision",hash(saved)).put("sourceRevision",hash(saved));write.set("executedChange",change);ObjectNode verify=obj().put("sheetId","keep").put("range","A1:F6").put("kind","matches_structure");verify.set("write",write);assertTrue(AgentTools.verify(saved,verify).path("passed").asBoolean());}
    public void testConfirmationScopeLastSheetAndDependenciesReject(){ObjectNode noForce=action();noForce.remove("force");reject(()->StructureManifest.preview(snapshot(),noForce,scopes()));ObjectNode same=action();same.put("fallbackSheetId","s");reject(()->StructureManifest.preview(snapshot(),same,scopes()));reject(()->StructureManifest.preview(snapshot(),action(),arr().add(obj().put("sheetId","s").put("range","A1:E6"))));ObjectNode last=snapshot();((ObjectNode)last.path("sheets")).remove("keep");last.set("sheetOrder",arr().add("s"));reject(()->StructureManifest.preview(last,action(),scopes()));ObjectNode hidden=snapshot();((ObjectNode)hidden.path("sheets").path("keep")).put("hidden",1);reject(()->StructureManifest.preview(hidden,action(),scopes()));ObjectNode formula=snapshot();((ObjectNode)formula.path("sheets").path("keep").path("cellData").path("0").path("0")).put("f","=Delete!A1");reject(()->StructureManifest.preview(formula,action(),scopes()));}
    public void testIndependentGateAndTamper(){ArrayNode actions=arr().add(action());reject(()->WriteManifest.classify(actions,false,false,false,false,false,false,false,true));assertEquals("controlled-values",WriteManifest.classify(actions,false,false,false,false,false,false,false,false,true));ObjectNode m=StructureManifest.preview(snapshot(),action(),scopes());((ObjectNode)m.path("structurePatch")).put("fallbackSheetId","wrong");reject(()->StructureManifest.apply(snapshot(),m));}
}
